/* WineMetalGL Wine module: what winemetalgl.dll (PE) and winemetalgl.so
 * (unix) share.
 *
 * The PE side is Wine's opengl32.dll for applications: opengl32.dll forwards
 * every export to winemetalgl.dll, whose GL functions make one unix call
 * each (generated by tools/gen/wine_gen.py) and whose WGL functions make the
 * calls below. The unix side runs the WineMetalGL core and owns contexts,
 * drawables and pixel formats; Wine's own opengl32, win32u OpenGL and
 * winemac OpenGL code are not used.
 *
 * The WGL parameter structs hold fixed-width fields only, so 32-bit (wow64)
 * and 64-bit callers share their layout. Handles and client pointers travel
 * as UINT64, zero-extended from 32-bit callers. */
#ifndef WMGL_WINE_H
#define WMGL_WINE_H

#include "wmgl_gltypes.h"
#include "wine_gl_params.gen.h"

/* Unix call status: the call queued debug messages for this thread, which
 * the PE side delivers before returning to the application. */
#define WMGL_STATUS_DEBUG_MESSAGES 0x00000103 /* STATUS_PENDING */

/* Batched GL calls (winemetalgl.c wmgl_batch): one unix call runs a
 * thread's batch, records of a header and a GL command's parameter struct
 * (in the caller's layout), then any data the struct points to. Records are
 * multiples of 8 bytes; codes are GL commands' (above unix_wmgl_batch). */
struct wmgl_batch_params
{
    UINT64 data;
    UINT size;
};

struct wmgl_batch_record
{
    UINT code;
    UINT size;  /* bytes of the record, header included */
};

/* Same as include/winemetalgl/driver.h. */
struct wmgl_pixel_format
{
    int draw_to_window, draw_to_pbuffer, double_buffer, stereo;
    int color_bits, red_bits, green_bits, blue_bits, alpha_bits;
    int red_shift, green_shift, blue_shift, alpha_shift;
    int depth_bits, stencil_bits, accum_bits, aux_buffers;
    int sample_buffers, samples, srgb_capable, float_components;
    int max_pbuffer_width, max_pbuffer_height, max_pbuffer_pixels;
};

/* Child windows a window's layer leaves room for (wmgl_window_placement). */
#define WMGL_MAX_HOLES 8

struct wmgl_rect
{
    INT x, y, width, height;
};

/* Where a window DC draws: its window, and the window's client area in
 * pixels no DPI awareness scaled (the PE side asks user32, whose answers are
 * stable across Wine versions; the unix side keeps no window state of its
 * own beyond its layer). */
struct wmgl_window_placement
{
    UINT64 hwnd;        /* 0: not a window DC */
    UINT64 top_level;
    INT x, y, width, height;  /* the client area within the top-level window's client area */
    INT top_level_width, top_level_height;
    UINT screen_width;  /* the primary screen's width */
    INT clip_x, clip_y, clip_width, clip_height;  /* the part of it its ancestors show, likewise */
    BOOL visible;
    /* Its visible child windows without a drawable of their own, likewise:
     * Wine draws those into the top-level window, under the layer, which
     * shows them through holes (the video window a movie player gives the
     * GL window, say). */
    UINT hole_count;
    struct wmgl_rect holes[WMGL_MAX_HOLES];
};

/* forget_window: a destroyed window's drawable goes. */
struct wmgl_forget_window_params
{
    UINT64 hwnd;
};

/* place_window: a window's child windows changed, between swaps. */
struct wmgl_place_window_params
{
    struct wmgl_window_placement window;
};

struct wmgl_init_params
{
    UINT64 program;         /* the program's path (client string), for the log */
    UINT64 host_version;    /* Wine's version (client string, or 0), for the log */
    UINT format_count;      /* out: pixel formats */
    UINT onscreen_count;    /* out: of which drawable to windows (the first ones) */
    INT core_major, core_minor;
    INT log_level;          /* out: the highest level the PE side's messages are kept at (-1: none) */
    BOOL ok;
};

/* log: a message of the PE side, into the core's log (category "pe"). */
struct wmgl_log_params
{
    UINT level;      /* 0 error, 1 warning, 2 info, 3 trace */
    UINT64 text;     /* client string */
};

struct wmgl_pixel_formats_params
{
    UINT64 formats;  /* client array of struct wmgl_pixel_format */
    UINT max;
    UINT count;      /* out */
};

struct wmgl_debug_message_params
{
    UINT64 buffer;   /* client buffer for the message text */
    UINT size;
    UINT64 callback; /* out: the application's callback and user parameter */
    UINT64 user;
    UINT source, type, id, severity;
    INT length;      /* out: the message's length (it may not fit) */
    UINT amd;        /* out: GLDEBUGPROCAMD (id, category, severity, length, message, user) */
    BOOL more;       /* out: another message follows */
    BOOL got;        /* out: a message was returned */
};

struct wmgl_get_pixel_format_params
{
    UINT64 hdc;
    UINT64 hwnd;     /* the DC's window, or 0 */
    INT ret;
};

struct wmgl_set_pixel_format_params
{
    UINT64 hdc;
    UINT64 hwnd;     /* the DC's window, or 0 */
    INT format;
    BOOL internal;  /* wglSetPixelFormatWINE: the format may be changed */
    BOOL ret;
};

struct wmgl_create_context_params
{
    UINT64 hdc;
    UINT64 hwnd;     /* the DC's window, or 0 */
    UINT64 share;    /* context handle or 0 */
    UINT64 attribs;  /* client array of int pairs, 0-terminated, or 0 */
    UINT64 ret;      /* out: context handle */
    UINT error;      /* out: Win32 error code */
};

struct wmgl_delete_context_params
{
    UINT64 context;
    BOOL ret;
    UINT error;      /* out: Win32 error code */
};

struct wmgl_make_current_params
{
    UINT64 draw_hdc;
    UINT64 read_hdc;
    struct wmgl_window_placement draw, read;
    UINT64 context;  /* 0: release the current context */
    BOOL ret;
    UINT error;
};

struct wmgl_share_lists_params
{
    UINT64 source;
    UINT64 dest;
    BOOL ret;
};

struct wmgl_copy_context_params
{
    UINT64 source;
    UINT64 dest;
    UINT mask;
    BOOL ret;
};

struct wmgl_swap_buffers_params
{
    UINT64 hdc;
    struct wmgl_window_placement window;
    BOOL ret;
};

struct wmgl_swap_interval_params
{
    INT interval;
    BOOL ret;
};

struct wmgl_create_pbuffer_params
{
    UINT64 hdc;
    UINT64 hwnd;
    INT format, width, height;
    UINT64 attribs;  /* client array of int pairs or 0 */
    UINT64 ret;      /* out: pbuffer handle */
    UINT error;
};

struct wmgl_pbuffer_params
{
    UINT64 pbuffer;
    UINT64 hdc;      /* get/release_pbuffer_dc: the memory DC the PE side made for it;
                        get_pbuffer_dc: out, the pbuffer's DC (an earlier one if it has one) */
    INT attribute;   /* query_pbuffer; bind/release_tex_image: the buffer */
    INT value;       /* query_pbuffer: out */
    UINT64 attribs;  /* set_pbuffer_attrib: client array */
    BOOL ret;
    UINT error;      /* out: Win32 error code, 0: ERROR_INVALID_HANDLE */
};

struct wmgl_query_renderer_params
{
    UINT64 hdc;      /* 0: the current context's renderer */
    INT renderer;
    UINT attribute;
    UINT64 value;    /* query_renderer_integer: client array of GLuint */
    UINT64 buffer;   /* query_renderer_string: client buffer */
    UINT size;
    BOOL ret;
};

struct wmgl_extensions_string_params
{
    UINT64 buffer;
    UINT size;
    UINT needed;     /* out: the length + 1 */
};

#endif
